using SpireLegacy;

public static class PilotRewardChecks
{
    public static void Run(Action<bool,string> check)
    {
        check(!PilotHealth.Affordable(6,6),"Exact HP cost is fatal");
        check(!PilotHealth.Affordable(5,6),"Over-budget HP cost is refused");
        check(PilotHealth.Affordable(7,6),"Survivable HP cost remains available");
        check(PilotHealth.Affordable(1,0),"Low health permits cards without immediate HP cost");
        check(PilotHealth.Penalty(7,6)>PilotHealth.Penalty(80,6),"Near-death self-damage has higher opportunity cost");
        PilotRewards.Card Attack(string id,int damage=6)=>new(id,1,damage,0,0,0,0,0,false,false,false,Attack:true);
        PilotRewards.Card Guard(string id,int block=5)=>new(id,1,0,block,0,0,0,0,false,false,false);
        var balanced=Enumerable.Range(0,6).Select(i=>Attack("a"+i)).Concat(Enumerable.Range(0,4).Select(i=>Guard("g"+i))).ToArray();
        var blocked=Attack("blocked",1000) with{Usable=false};
        check(PilotRewards.Pick([blocked,Guard("legal",7)],balanced)==1,"Permanent attack restriction overrides apparent reward damage");
        check(PilotRewards.Pick([blocked],balanced)==null,"All permanently blocked rewards can be skipped");
        check(double.IsFinite(PilotRewards.Score(blocked,balanced)),"Blocked reward score remains serializable");
        var attacks=balanced.Where(c=>c.Damage>0).ToArray();
        check(PilotRewards.Pick([Attack("hit",10),Guard("ward",6)],attacks)==1,"Reward policy fills defensive deck deficit");
        var duplicate=Attack("duplicate");var full=balanced.Concat(new[]{duplicate,duplicate}).ToArray();
        check(PilotRewards.Pick([duplicate,new("power",1,0,0,0,0,0,0,true,false,false)],full)==1,"Reward policy prefers new scaling to third redundant attack");
        check(PilotRewards.Pick([duplicate with{Cost=3},Guard("poor",1) with{Cost=3}],full)==null,"Reward policy can skip weak redundant offers");
        var fuel=new PilotRewards.Card("fuel",1,0,0,1,0,0,0,false,true,false);
        check(PilotRewards.Pick([Attack("hit",10),new("engine",1,0,0,0,0,0,0,true,false,true)],[fuel,fuel])==1,"Reward policy builds on existing exhaust support");
        var poison=new PilotRewards.Card("seed",1,0,0,0,0,4,0,false,false,false);
        check(PilotRewards.Pick([Attack("hit",10),poison with{Id="new",Poison=3}],[poison,poison])==1,"Reward policy builds on established Poison");
        var tie=new[]{Attack("z"),Attack("a")};
        check(tie[PilotRewards.Pick(tie,balanced)!.Value].Id=="a","Reward tie breaks deterministically by stable ID");
        check(PilotRewards.Pick([],balanced)==null,"Empty reward offer is safe");
        var counter=Attack("counter") with{Special="guard_bonus",SpecialAmount=10};
        check(PilotRewards.Pick([Attack("hit",12),counter],balanced)==1,"Block support makes guarded reward competitive");
        check(PilotRewards.Pick([Attack("hit",12),counter],attacks)==0,"No Block support does not promise guarded bonus");
        var ambush=counter with{Id="ambush",Special="marked_bonus"};
        check(PilotRewards.Pick([Attack("hit",12),ambush],[poison,poison])==1,"Poison supports marked reward");
        check(PilotRewards.Pick([Attack("hit",12),ambush],[Attack("mark") with{Vulnerable=2}])==1,"Vulnerable supports marked reward");
        check(PilotRewards.Pick([Attack("hit",12),ambush],[Attack("weak") with{Weak=2}])==0,"Weak alone does not activate marked bonus");
        check(PilotRewards.Pick([Attack("hit",10) with{Cost=2},Attack("axe",9) with{Cost=2,Special="execute",SpecialAmount=2}],balanced)==1,"Partial execution value can distinguish otherwise similar rewards");
        var retained=Attack("retained",3) with{Special="retain_damage",SpecialAmount=6};
        check(PilotRewards.Pick([Attack("hit",5),retained],balanced)==1,"Retention growth has discounted reward value");
        check(PilotRewards.Score(counter,[])==PilotRewards.Score(counter with{Special="none"},[]),"Empty deck provides no guarded support");
        check(PilotRewards.Score(ambush with{Special="unknown"},balanced)==PilotRewards.Score(ambush with{Special="none"},balanced),"Unmodeled conditions are not guessed");
        var repeated=Attack("repeated",12) with{Special="marked_bonus",SpecialAmount=2,Hits=2};
        check(PilotRewards.Pick([Attack("flat",14),repeated],[poison])==1,"Supported marked bonus values each hit of a reward");
        check(PilotRewards.Pick([Attack("flat",14),repeated],attacks)==0,"Repeated marked reward still needs support");
        check(PilotRewards.Pick([Guard("flat",5),Guard("stored",3) with{Special="retain_block",SpecialAmount=6}],balanced)==1,"Retained Block growth is valued without inventing damage");
        var shield=Attack("slam",0) with{Special="block_damage"};
        check(PilotRewards.Pick([Attack("flat",11),shield],[Guard("large",16)])==1,"Large Block support gives a Block finisher prospective value");
        check(PilotRewards.Pick([shield],attacks)==null,"Unsupported Block finisher can be skipped");
        var chain=Attack("chain",0) with{Special="chain_damage",SpecialAmount=4};
        check(PilotRewards.Pick([Attack("flat",5),chain],attacks)==1,"Cheap attacks support a chain finisher");
        check(PilotRewards.Pick([chain],balanced.Select(c=>c with{Cost=3}).ToArray())==null,"Expensive attacks do not promise chain fuel");
        var ash=Attack("ash",3) with{Special="exhaust_damage",SpecialAmount=3};
        var expendable=balanced.Select(c=>c with{SelfExhaust=true}).ToArray();
        check(PilotRewards.Pick([Attack("flat",8),ash],expendable)==1,"Self-exhausting cards support exhaust damage rewards");
        check(PilotRewards.Pick([Attack("flat",8),ash],attacks)==0,"Ordinary attacks do not promise exhaust buildup");
        check(PilotHealth.NeedsEmergencyBlock(5,2,7),"Exactly lethal incoming damage requests emergency Block");
        check(!PilotHealth.NeedsEmergencyBlock(5,3,7),"Survivable damage conserves emergency potion");
        check(!PilotHealth.NeedsEmergencyBlock(1,12,12),"Existing Block avoids redundant potion use");
        var delayedAttack=Attack("brave",5) with{NextEnergy=1};
        var execution=Attack("axe",9) with{Cost=2,Special="execute",SpecialAmount=2};
        check(PilotRewards.Pick([execution,delayedAttack],balanced)==1,"Next-turn Energy gives Brave Advance credit against a conditional two-cost attack");
        check(PilotRewards.Score(delayedAttack,balanced)<PilotRewards.Score(delayedAttack with{NextEnergy=0,Energy=1},balanced),"Delayed Energy is discounted against immediate Energy");
        check(PilotRewards.Pick([Guard("plain",5),Guard("mail",3) with{NextBlock=6}],balanced)==1,"Delayed Block has value distinct from immediate Block");
        check(PilotRewards.Score(Guard("late",0) with{NextBlock=6},balanced)<PilotRewards.Score(Guard("now",6),balanced),"Delayed Block is not full immediate protection");
        check(PilotRewards.Pick([Attack("plain",5),Attack("running",3) with{NextDraw=2}],balanced)==1,"Next-turn draw gets prospective reward value");
        check(PilotRewards.Score(Attack("late",0) with{NextDraw=2},balanced)<PilotRewards.Score(Attack("now",0) with{Draw=2},balanced),"Delayed draw is discounted against immediate draw");
        var guarded=Attack("conditional",6) with{Special="guard_bonus",SpecialAmount=4};
        var sparse=Enumerable.Range(0,7).Select(i=>Guard("g"+i,5)).Concat(Enumerable.Range(0,8).Select(i=>Attack("a"+i))).ToArray();
        check(PilotRewards.Pick([guarded,Guard("defense",7)],sparse)==0,"Control preserves its conditional attack preference");
        check(PilotRewards.Pick([guarded,Guard("defense",7)],sparse,true)==1,"Defensive quality objective can prefer an affordable guard");
        var strong=Enumerable.Range(0,7).Select(i=>Guard("g"+i,10)).Concat(Enumerable.Range(0,8).Select(i=>Attack("a"+i))).ToArray();
        check(PilotRewards.Pick([guarded,Guard("defense",7)],strong,true)==0,"Sufficient defense restores the ordinary attack choice");
        check(PilotRewards.Score(Guard("g",7),strong,true)==PilotRewards.Score(Guard("g",7),strong),"Sufficient coverage earns no defensive bonus");
        check(PilotRewards.Pick([Guard("tiny",1)],attacks,true)==null,"Defense objective does not force a weak one-Block reward");
        check(PilotRewards.Score(Guard("g",12),attacks,true)-PilotRewards.Score(Guard("g",12),attacks)<=3,"Defensive preference is bounded");
        check(PilotRewards.Score(Guard("empty",7),[],true)==PilotRewards.Score(Guard("empty",7),[]),"Empty deck avoids unsupported coverage assumptions");
        check(PilotRewards.Score(Guard("later",0) with{NextBlock=10},attacks,true)==PilotRewards.Score(Guard("later",0) with{NextBlock=10},attacks),"Delayed protection is not immediate defensive coverage");
    }
}
